with feeders as (
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , USERNAME as POLICY_CAPTURED_BY_USER_REFERENCE
        , cast(null as varchar) as APPROVED_BY_USER_REFERENCE
        , cast(null as varchar) as WEB_USER_IDENTIFIER
        , 'BJAZ_POLICY_SUMMARY' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_policy_summary') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , cast(null as varchar) as POLICY_CAPTURED_BY_USER_REFERENCE
        , APPROVED_BY as APPROVED_BY_USER_REFERENCE
        , WEB_USERID as WEB_USER_IDENTIFIER
        , 'BJAZ_POLICY_BASES_EXTN' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_policy_bases_extn') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
),

resolved as (
    select
        HUB_POLICY_HK,
        max(case when SOURCE_RUN = 'opus_health_delta3' then POLICY_CAPTURED_BY_USER_REFERENCE end) as POLICY_CAPTURED_BY_USER_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then APPROVED_BY_USER_REFERENCE end) as APPROVED_BY_USER_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then WEB_USER_IDENTIFIER end) as WEB_USER_IDENTIFIER,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_POLICY_HK
),

hashed as (
    select
        *,
        case when POLICY_CAPTURED_BY_USER_REFERENCE is not null or APPROVED_BY_USER_REFERENCE is not null or WEB_USER_IDENTIFIER is not null
                     then md5(upper(coalesce(cast(POLICY_CAPTURED_BY_USER_REFERENCE as varchar), '') || '|' || coalesce(cast(APPROVED_BY_USER_REFERENCE as varchar), '') || '|' || coalesce(cast(WEB_USER_IDENTIFIER as varchar), '')))
                end as SAT_COMMON_BUSINESS_AUDIT_HASHDIFF
    from resolved
)

select * from hashed
where HUB_POLICY_HK is not null
  and SAT_COMMON_BUSINESS_AUDIT_HASHDIFF is not null
